136|/// Read one `run.json` (`Err` says why when it exists but does not parse).
137|pub fn read_record(dir: &Path) -> Result<Option<RunRecord>, String> {
138|    let p = dir.join("run.json");
139|    let bytes = match std::fs::read(&p) {
140|        Ok(b) => b,
141|        Err(_) => return Ok(None),
142|    };
143|    let mut rec: RunRecord = serde_json::from_slice(&bytes)
144|        .map_err(|e| format!("{} does not parse: {e}", p.display()))?;
145|    // A pending record (`running`, or `waiting_quota` while a detached alarm sleeps) whose
146|    // background is gone (the pid is dead, or it never reported one within the start grace) is a
147|    // run that DIED: say so on disk, so `--status`, `--wait` and the one-live-run guard never wait
148|    // on a ghost.
149|    if is_pending(&rec.status) && !is_live(&rec) {
150|        rec.status = "died".into();
151|        rec.ended = Some(chrono::Utc::now().to_rfc3339());
152|        rec.args = None;
153|        let _ = write_record(dir, &rec);
154|    }
155|    Ok(Some(rec))
156|}
