158|/// How long a pending record may go without a reported pid before it counts as dead
159|/// (the background reports its pid within its first second).
160|const START_GRACE_SEC: i64 = 120;
161|
162|/// Whether a status means the run's background is still supposed to be alive: `running`, or
163|/// `waiting_quota` while a detached run's alarm sleeps until the quota window resets.
164|pub fn is_pending(status: &str) -> bool {
165|    status == "running" || status == "waiting_quota"
166|}
167|
168|/// Whether a pending record's background is alive: its reported pid exists, or no pid was
169|/// reported yet and the record is younger than [`START_GRACE_SEC`]. Anything else is dead.
170|pub fn is_live(rec: &RunRecord) -> bool {
171|    if !is_pending(&rec.status) {
172|        return false;
173|    }
174|    match rec.pid {
175|        Some(pid) if pid > 0 => crate::liveness::proc::pid_alive(pid as u32, &rec.pid_start),
176|        _ => match chrono::DateTime::parse_from_rfc3339(&rec.started) {
177|            Ok(t) => {
178|                (chrono::Utc::now() - t.with_timezone(&chrono::Utc)).num_seconds() < START_GRACE_SEC
179|            }
180|            Err(_) => false,
181|        },
182|    }
183|}
