209|/// Whether a live work run exists for the task (a `running` or `waiting_quota` record): its id,
210|/// or `None`.
211|pub fn live_run(work_root: &Path) -> Option<String> {
212|    run_dirs(work_root).into_iter().find_map(|(_, dir)| {
213|        read_record(&dir)
214|            .ok()
215|            .flatten()
216|            .filter(|r| is_pending(&r.status))
217|            .map(|r| r.id)
218|    })
219|}
