221|/// (0.2.4, F89-2) The id of any LIVE run of the task other than the one at `exclude`, or `None`.
222|/// Used under the admission lock so a start/resume/alarm refuses while another run is alive.
223|pub fn other_live_run(work_root: &Path, exclude: &Path) -> Option<String> {
224|    run_dirs(work_root).into_iter().find_map(|(_, dir)| {
225|        if dir == exclude {
226|            return None;
227|        }
228|        read_record(&dir)
229|            .ok()
230|            .flatten()
231|            .filter(|r| is_pending(&r.status) && is_live(r))
232|            .map(|r| r.id)
233|    })
