246|/// (0.2.4, F89-2) The task-level admission lock file (held only across the claim's
247|/// check-and-write, released on drop or when the process dies).
248|pub const ADMISSION_LOCK: &str = ".admission.lock";
249|
250|/// (0.2.4, F89-2) An exclusive OS lock on the task's admission-lock file, released when dropped
251|/// (or when the process dies). The same advisory-lock mechanism the telemetry spool uses.
252|pub struct AdmissionLock {
253|    _file: std::fs::File,
254|}
255|
256|/// (0.2.4, F89-2) Take the task's admission lock (one claim at a time across starts, resumes and
257|/// the detached alarm), waiting at most 10 s. The guard releases the lock when dropped.
258|pub fn admission_lock(work_root: &Path) -> Result<AdmissionLock, String> {
259|    let _ = std::fs::create_dir_all(work_root);
260|    let path = work_root.join(ADMISSION_LOCK);
261|    let file = std::fs::OpenOptions::new()
262|        .read(true)
263|        .write(true)
264|        .create(true)
265|        .truncate(false)
266|        .open(&path)
267|        .map_err(|e| format!("could not open the task admission lock ({e})"))?;
268|    let started = std::time::Instant::now();
269|    loop {
270|        match file.try_lock() {
271|            Ok(()) => return Ok(AdmissionLock { _file: file }),
272|            Err(std::fs::TryLockError::WouldBlock) => {
273|                if started.elapsed() >= std::time::Duration::from_secs(10) {
274|                    return Err(
275|                        "the task's admission lock stayed busy (another c3 work is admitting a run)"
276|                            .into(),
277|                    );
278|                }
279|                std::thread::sleep(std::time::Duration::from_millis(25));
280|            }
281|            Err(std::fs::TryLockError::Error(e)) => {
282|                return Err(format!("could not take the task admission lock ({e})"))
283|            }
284|        }
285|    }
