288|/// A directory-name-safe form of a provider label or model id: everything outside
289|/// `[A-Za-z0-9._-]` becomes `-` (never empty).
290|fn dir_part(s: &str) -> String {
291|    let mut out: String = s
292|        .chars()
293|        .map(|c| {
294|            if c.is_ascii_alphanumeric() || c == '.' || c == '_' || c == '-' {
295|                c
296|            } else {
297|                '-'
298|            }
299|        })
300|        .collect();
301|    out.truncate(60);
302|    if out.is_empty() {
303|        out.push('x');
304|    }
305|    out
306|}
