308|/// The next record directory of a task: `<work>/<NN>-<provider>-<model>` with NN the next
309|/// 2-digit sequence (never one that exists).
310|pub fn allocate(
311|    work_root: &Path,
312|    provider: &str,
313|    model: &str,
314|) -> Result<(String, i64, PathBuf), String> {
315|    let next = run_dirs(work_root)
316|        .iter()
317|        .map(|(seq, _)| *seq)
318|        .max()
319|        .unwrap_or(0)
320|        + 1;
321|    for seq in next..(next + 50) {
322|        let id = format!("{seq:02}-{}-{}", dir_part(provider), dir_part(model));
323|        let dir = work_root.join(&id);
324|        if !dir.exists() {
325|            std::fs::create_dir_all(&dir).map_err(|e| {
326|                format!(
327|                    "could not create the work record directory '{}' ({e})",
328|                    dir.display()
329|                )
330|            })?;
331|            return Ok((id, seq, dir));
332|        }
333|    }
334|    Err(format!(
335|        "no free work record directory under '{}' (50 tried); remove old work runs",
336|        work_root.display()
337|    ))
