342|/// One read-only git command's stdout lines (empty on any failure).
343|fn git_lines(repo: &Path, args: &[&str]) -> Vec<String> {
344|    std::process::Command::new("git")
345|        .arg("-C")
346|        .arg(repo)
347|        .args(args)
348|        .output()
349|        .map(|o| {
350|            if o.status.success() {
351|                String::from_utf8_lossy(&o.stdout)
352|                    .lines()
353|                    .map(|l| l.to_string())
354|                    .collect()
355|            } else {
356|                Vec::new()
357|            }
358|        })
359|        .unwrap_or_default()
360|}
