372|/// The path a `git status --short` line names (the `R  old -> new` form names the new path).
373|fn path_of_status_line(line: &str) -> String {
374|    let p = line.get(3..).unwrap_or("").trim();
375|    match p.split_once(" -> ") {
376|        Some((_, new)) => new.trim().to_string(),
377|        None => p.to_string(),
378|    }
379|}
