381|/// (0.2.4, F89-7) The content hash of a working-tree path (`git hash-object`), `"<absent>"` when
382|/// the file does not exist (a deletion), `""` when git cannot hash it.
383|pub fn hash_of(repo: &Path, path: &str) -> String {
384|    if !repo.join(path).exists() {
385|        return "<absent>".to_string();
386|    }
387|    git_lines(repo, &["hash-object", "--", path])
388|        .into_iter()
389|        .next()
390|        .unwrap_or_default()
391|}
392|
393|/// (0.2.4, F89-7) The content hash of every path dirty at the baseline (`git status --short`
394|/// before the run). `files_changed` compares against this so a path already dirty but edited
395|/// further by the worker is reported, and one left untouched is not.
396|pub fn baseline_hashes(repo: &Path, before: &[String]) -> BTreeMap<String, String> {
397|    let mut m = BTreeMap::new();
398|    for line in before {
399|        let p = path_of_status_line(line);
400|        if !p.is_empty() {
401|            let h = hash_of(repo, &p);
402|            m.insert(p, h);
403|        }
404|    }
405|    m
406|}
407|
408|/// (0.2.4, F89-7) The files the run changed, by CONTENT IDENTITY: every path dirty after the run
409|/// whose current content hash differs from its baseline hash (a new/untracked path has no baseline
410|/// hash, so it is listed; a pre-dirty path the worker edited further differs, so it is listed; a
411|/// pre-dirty path left untouched matches, so it is not). After-order, deduplicated.
412|pub fn files_changed(
413|    baseline_hashes: &BTreeMap<String, String>,
414|    after: &[String],
415|    repo: &Path,
416|) -> Vec<String> {
417|    let mut out: Vec<String> = Vec::new();
418|    for line in after {
419|        let p = path_of_status_line(line);
420|        if p.is_empty() || out.contains(&p) {
421|            continue;
422|        }
423|        let now = hash_of(repo, &p);
424|        match baseline_hashes.get(&p) {
425|            Some(b) if *b == now => {} // dirty before and still the same content: not the worker's
426|            _ => out.push(p),
427|        }
428|    }
429|    out
430|}
