432|/// `diff.txt`: the baseline, the after state and the diff stat.
433|pub fn diff_text(before: &[String], after: &[String], stat: &[String]) -> String {
434|    let block = |title: &str, lines: &[String]| -> String {
435|        if lines.is_empty() {
436|            format!("{title}: (empty)\n")
437|        } else {
438|            format!("{title}:\n{}\n", lines.join("\n"))
439|        }
440|    };
441|    format!(
442|        "{}\n{}\n{}",
443|        block("git status --short (before the run)", before),
444|        block("git status --short (after the run)", after),
445|        block("git diff --stat (after the run)", stat)
446|    )
