451|/// What c3 reads out of a work run's event stream (`events.jsonl`).
452|#[derive(Debug, Clone, Default)]
453|pub struct EventSummary {
454|    pub has_result: bool,
455|    /// The result event's `result` text (the report).
456|    pub result_text: String,
457|    pub is_error: bool,
458|    pub num_turns: Option<i64>,
459|    /// How many assistant events the stream holds (the `turns` fallback).
460|    pub assistant_count: i64,
461|    /// The last assistant text (the report of a run that died without a result).
462|    pub last_assistant_text: String,
463|    /// Tool name -> call count.
464|    pub tool_calls: BTreeMap<String, i64>,
465|    /// The result's `usage` merged with its `total_cost_usd` when present.
466|    pub usage: Option<Value>,
467|}
468|
469|/// (0.2.4, F89-5) The usage of a claude `result` event, rebuilt from an ALLOW LIST of numeric
470|/// counters — the token columns from the `usage` object plus `total_cost_usd`, `duration_ms` and
471|/// `num_turns` from the result. Any other field (a sentinel, a secret) is dropped. `None` when no
472|/// counter is present.
473|fn claude_usage(result_obj: &Value) -> Option<Value> {
474|    let mut map = serde_json::Map::new();
475|    if let Some(u) = result_obj.get("usage").filter(|v| v.is_object()) {
476|        for k in [
477|            "input_tokens",
478|            "output_tokens",
479|            "cache_creation_input_tokens",
480|            "cache_read_input_tokens",
481|        ] {
482|            if let Some(n) = u.get(k).and_then(|v| v.as_i64()) {
483|                map.insert(k.into(), Value::from(n));
484|            }
485|        }
486|    }
487|    for k in ["num_turns", "duration_ms"] {
488|        if let Some(n) = result_obj
489|            .get(k)
490|            .and_then(|v| v.as_i64().or_else(|| v.as_str().and_then(|x| x.parse().ok())))
491|        {
492|            map.insert(k.into(), Value::from(n));
493|        }
494|    }
495|    if let Some(c) = result_obj.get("total_cost_usd").and_then(|v| {
496|        v.as_f64()
497|            .or_else(|| v.as_str().and_then(|x| x.parse().ok()))
498|    }) {
499|        map.insert("total_cost_usd".into(), Value::from(c));
500|    }
501|    (!map.is_empty()).then(|| Value::Object(map))
502|}
