474|/// The terminal verdict of `engine`'s event stream (F89-8): success requires the engine's own
475|/// successful terminal event, an error terminal is a failure, and an empty stream is `None`.
476|pub fn terminal_outcome(engine: WorkerEngine, events_text: &str) -> Terminal {
477|    match engine {
478|        WorkerEngine::Claude => {
479|            let s = summarize_events(events_text);
480|            if !s.has_result {
481|                Terminal::None
482|            } else if s.is_error {
483|                Terminal::Error
484|            } else {
485|                Terminal::Success
486|            }
487|        }
488|        WorkerEngine::Codex => {
489|            if !crate::engines::codex::parse_error(events_text).is_empty() {
490|                return Terminal::Error;
491|            }
492|            let mut saw_completed = false;
493|            for line in events_text.split(['\r', '\n']) {
494|                let t = line.trim();
495|                if !t.starts_with('{') {
496|                    continue;
497|                }
498|                let Ok(obj) = serde_json::from_str::<Value>(t) else {
499|                    continue;
