501|                match obj.get("type").and_then(|v| v.as_str()).unwrap_or("") {
502|                    "turn.failed" => return Terminal::Error,
503|                    "turn.completed" => saw_completed = true,
504|                    "item.completed"
505|                        if obj
506|                            .get("item")
507|                            .and_then(|i| i.get("type"))
508|                            .and_then(|v| v.as_str())
