961|/// The alarm's decision for one sleep slice: sleep a bounded slice, resume now, or give up because
962|/// the resume cap is spent. A PURE function of the clock, the reset time, the kick file and the
963|/// resume count - unit-tested without any real sleeping.
964|#[derive(Debug, PartialEq, Eq)]
965|pub(crate) enum AlarmAction {
