971|/// [`AlarmAction`] for `now`: give up when `resumes >= max`; resume when the kick file exists or
972|/// the window has reset; else sleep up to [`ALARM_SLICE_SEC`] (never past `resume_at`, never 0).
973|pub(crate) fn next_action(
974|    now: DateTime<Utc>,
975|    resume_at: DateTime<Utc>,
976|    kick_exists: bool,
977|    resumes: i64,
978|    max: i64,
979|) -> AlarmAction {
980|    if resumes >= max {
981|        return AlarmAction::GiveUp;
982|    }
983|    if kick_exists || now >= resume_at {
984|        return AlarmAction::Resume;
985|    }
986|    let secs = (resume_at - now).num_seconds().clamp(1, ALARM_SLICE_SEC);
987|    AlarmAction::Sleep(Duration::from_secs(secs as u64))
