788|/// Classify one work attempt from ITS OWN stream and stderr (never a prior attempt's): the base
789|/// status (`timeout` | `done` | `died`), turned into `quota` when the attempt did not succeed and
790|/// the engine found a usage limit. Returns `(status, quota_text, reset_at)`.
791|fn classify_attempt(
792|    engine: WorkerEngine,
793|    events_text: &str,
794|    stderr_text: &str,
795|    timed_out: bool,
796|    exit_code: Option<i32>,
797|) -> (String, String, Option<DateTime<Utc>>, String) {
798|    let (quota_text, reset_at) = engines::quota_evidence(engine, events_text, stderr_text);
799|    let outcome = engines::terminal_outcome(engine, events_text);
800|    // (0.2.4, F89-8) A rejecting rate-limit / quota wording takes precedence over exit 0 (so a run
801|    // resumes), UNLESS the engine also emitted a clean successful terminal. Otherwise success
802|    // requires BOTH exit 0 AND the engine's successful terminal event; an error terminal or an
803|    // empty stream fails closed (`died`), never `done`.
804|    if !quota_text.is_empty() && outcome != engines::Terminal::Success {
805|        return ("quota".to_string(), quota_text, reset_at, String::new());
806|    }
807|    if timed_out {
808|        return ("timeout".to_string(), quota_text, reset_at, String::new());
809|    }
810|    let (status, reason) = match outcome {
811|        engines::Terminal::Success if exit_code == Some(0) => ("done", String::new()),
812|        engines::Terminal::Success => (
813|            "died",
814|            format!(
815|                "the engine reported success but the process exited {}",
816|                exit_code.map(|c| c.to_string()).unwrap_or_else(|| "(none)".into())
817|            ),
818|        ),
819|        engines::Terminal::Error => ("died", "the engine reported an error result".to_string()),
820|        engines::Terminal::None => ("died", "no terminal event".to_string()),
821|    };
822|    (status.to_string(), quota_text, reset_at, reason)
