876|/// The entry point: `--status`/`--wait` read the records only; `--detach-id` is the
877|/// background; anything else is a run (foreground, or detached once its record exists).
878|pub fn run(mut o: Options) -> i32 {
879|    if o.status || o.wait {
880|        return detach::query(&o);
881|    }
882|    if !o.detach_id.trim().is_empty() {
883|        return detach::background(&o);
884|    }
885|    if o.task.trim().is_empty() {
886|        return refuse("--task is required (see c3 work --help).");
887|    }
888|    if o.resume || o.kick {
889|        return resume_or_kick(&o);
890|    }
891|    let pre = match prepare(&mut o) {
892|        Ok(p) => p,
893|        Err(why) => return refuse(&why),
894|    };
895|    // (0.2.4, F89-1/F89-2) One task-level admission for starts: hold the admission lock across the
896|    // live-run check, the allocation and the initial claim, so two starts cannot both pass. A
897|    // foreground run writes its OWN pid + start time BEFORE the child is spawned (the owner that
898|    // keeps the record `running` past the start grace); a detached run leaves the pid to its
899|    // background (claimed within its first second).
900|    let lock = match record::admission_lock(&pre.work_root) {
901|        Ok(l) => l,
902|        Err(e) => return refuse(&e),
903|    };
904|    if let Some(id) = record::live_run(&pre.work_root) {
905|        return refuse(&format!(
906|            "task '{}' already has a live work run ({id}); c3 work --task {}{} --wait waits for it",
907|            o.task,
908|            o.task,
909|            if o.collab_dir != ".collab" {
910|                format!(" --collab-dir \"{}\"", o.collab_dir)
911|            } else {
912|                String::new()
913|            }
914|        ));
915|    }
916|    let (id, seq, rec_dir) = match record::allocate(&pre.work_root, &pre.provider, &pre.model) {
917|        Ok(x) => x,
918|        Err(e) => return refuse(&e),
919|    };
920|    let (pid, pid_start) = if o.detach {
921|        (None, String::new())
922|    } else {
923|        let (p, s) = record::self_owner();
924|        (Some(p), s)
925|    };
926|    let rec = RunRecord {
927|        id: id.clone(),
928|        task: o.task.clone(),
929|        seq,
930|        provider: pre.provider.clone(),
931|        model: pre.model.clone(),
932|        engine: pre.engine.as_str().into(),
933|        child_env_scrubbed: Vec::new(),
934|        started: iso_now(),
935|        status: "running".into(),
936|        timeout_sec: o.timeout_sec,
937|        pid,
938|        pid_start,
939|        max_resumes: eff_max_resumes(&o),
940|        quota_window_sec: eff_window(&o, pre.entry.quota_window_sec),
941|        unrestricted: pre.unrestricted,
942|        permission: pre.permission.clone(),
943|        args: o.detach.then(|| detach::wire_of(&o, &pre.collab_root)),
944|        ..Default::default()
945|    };
946|    if let Err(e) = write_record(&rec_dir, &rec) {
947|        return refuse(&format!(
948|            "the work run could not write {} ({e}); nothing was started.",
949|            rec_dir.join("run.json").display()
950|        ));
951|    }
952|    drop(lock);
953|    if o.detach {
954|        return detach::start_detached(&o, &pre, &id, &rec_dir);
955|    }
956|    run_prepared(&o, &rec_dir, &id, seq, false)
957|}
