959|// ------------------------------------------------------------------ the quota resume / alarm
960|
961|/// The alarm's decision for one sleep slice: sleep a bounded slice, resume now, or give up because
962|/// the resume cap is spent. A PURE function of the clock, the reset time, the kick file and the
963|/// resume count - unit-tested without any real sleeping.
964|#[derive(Debug, PartialEq, Eq)]
965|pub(crate) enum AlarmAction {
966|    Sleep(Duration),
967|    Resume,
968|    GiveUp,
969|}
970|
971|/// [`AlarmAction`] for `now`: give up when `resumes >= max`; resume when the kick file exists or
972|/// the window has reset; else sleep up to [`ALARM_SLICE_SEC`] (never past `resume_at`, never 0).
973|pub(crate) fn next_action(
974|    now: DateTime<Utc>,
975|    resume_at: DateTime<Utc>,
976|    kick_exists: bool,
977|    resumes: i64,
978|    max: i64,
979|) -> AlarmAction {
980|    if resumes >= max {
981|        return AlarmAction::GiveUp;
982|    }
983|    if kick_exists || now >= resume_at {
984|        return AlarmAction::Resume;
985|    }
986|    let secs = (resume_at - now).num_seconds().clamp(1, ALARM_SLICE_SEC);
987|    AlarmAction::Sleep(Duration::from_secs(secs as u64))
988|}
989|
990|/// An RFC3339 instant, defaulting to now (resume at once) when it does not parse.
991|fn parse_utc(rfc: &str) -> DateTime<Utc> {
992|    DateTime::parse_from_rfc3339(rfc)
993|        .map(|t| t.with_timezone(&Utc))
994|        .unwrap_or_else(|_| Utc::now())
995|}
996|
997|/// An RFC3339 instant as a local wall-clock time (the string unchanged when it does not parse).
998|fn local_time(rfc: &str) -> String {
999|    match DateTime::parse_from_rfc3339(rfc) {
1000|        Ok(t) => t
1001|            .with_timezone(&chrono::Local)
1002|            .format("%Y-%m-%d %H:%M:%S %Z")
1003|            .to_string(),
1004|        Err(_) => rfc.to_string(),
1005|    }
1006|}
