1008|/// The session id to resume: the record's stored one, else the value after `--session-id` in its
1009|/// argv (a record that predates quota resume).
1010|fn session_from_argv(argv: &[String]) -> Option<String> {
1011|    argv.iter()
1012|        .position(|a| a == "--session-id")
1013|        .and_then(|i| argv.get(i + 1))
1014|        .cloned()
1015|}
