1017|/// Everything a resume needs, re-derived from the record and the roster (NOT from the brief: the
1018|/// session already holds it). Built once per `--resume`/`--kick` and once per detached alarm.
1019|struct ResumeEnv {
1020|    engine: WorkerEngine,
1021|    repo_root: PathBuf,
1022|    launcher: String,
1023|    /// The child environment (claude's endpoint route) or `None` to inherit (codex/muse).
1024|    env: Option<Vec<(String, String)>>,
1025|    argv: Vec<String>,
1026|    prompt_delivery: c3_core::engine::PromptDelivery,
1027|    /// The resume nudge on stdin (claude/codex); empty for muse (it reads a `--prompt-file`).
1028|    stdin_text: String,
1029|    crt_quote: bool,
1030|    timeout_sec: i64,
1031|    max_resumes: i64,
1032|    window_sec: i64,
1033|}
