1035|fn resume_env(o: &Options, rec: &RunRecord, rec_dir: &Path) -> Result<ResumeEnv, String> {
1036|    let engine = WorkerEngine::parse(&rec.engine).ok_or_else(|| {
1037|        format!(
1038|            "the work record's engine '{}' is not a worker engine ({})",
1039|            rec.engine,
1040|            engines::WORKER_ENGINE_LIST
1041|        )
1042|    })?;
1043|    let (repo_root, _collab, _task_dir) = prepare_paths(o)?;
1044|    let roster = providers::read_reviewer_roster()?;
1045|    let entry = select_worker(&roster, &rec.provider)?;
1046|    let (env, _scrubbed) = worker_child_env(engine, &entry)?;
1047|    let launcher = resolve_worker_launcher(engine)?;
1048|    let session_id = if !rec.session_id.trim().is_empty() {
1049|        rec.session_id.clone()
1050|    } else {
1051|        session_from_argv(&rec.argv).unwrap_or_default()
1052|    };
1053|    // muse resumes through a `--prompt-file`; claude/codex through stdin.
1054|    let resume_prompt_file = rec_dir.join(".resume-prompt.md");
1055|    let (prompt_delivery, stdin_text) = match engine {
1056|        WorkerEngine::Muse => {
1057|            std::fs::write(&resume_prompt_file, RESUME_PROMPT)
1058|                .map_err(|e| format!("could not write the resume prompt ({e})"))?;
1059|            (c3_core::engine::PromptDelivery::PromptFile, String::new())
1060|        }
1061|        _ => (
1062|            c3_core::engine::PromptDelivery::Stdin,
1063|            RESUME_PROMPT.to_string(),
1064|        ),
1065|    };
1066|    let argv = engines::resume_args(
1067|        engine,
1068|        &rec.argv,
1069|        &session_id,
1070|        &resume_prompt_file.to_string_lossy(),
1071|    )
1072|    .ok_or_else(|| {
1073|        "the record has no session to resume (a codex run that never named a thread, or an argv without a session handoff)".to_string()
1074|    })?;
1075|    Ok(ResumeEnv {
1076|        engine,
1077|        repo_root,
1078|        launcher,
1079|        env,
1080|        argv,
1081|        prompt_delivery,
1082|        stdin_text,
1083|        crt_quote: matches!(engine, WorkerEngine::Claude),
1084|        timeout_sec: if rec.timeout_sec > 0 {
1085|            rec.timeout_sec
1086|        } else {
1087|            3600
1088|        },
1089|        max_resumes: eff_max_resumes_rec(o, rec),
1090|        window_sec: eff_window_rec(o, rec, entry.quota_window_sec),
1091|    })
