1094|/// Append the resume separator line and this attempt's stream to `events.jsonl` (verbatim, the
1095|/// whole record kept in order).
1096|fn append_resume(rec_dir: &Path, n: i64, attempt_events: &str) -> Result<(), String> {
1097|    use std::io::Write;
1098|    let path = rec_dir.join("events.jsonl");
1099|    let needs_nl = std::fs::read(&path)
1100|        .ok()
1101|        .map(|b| !b.is_empty() && b.last() != Some(&b'\n'))
1102|        .unwrap_or(false);
1103|    // (0.2.4, F89-3) Every open/write/flush error is propagated — the caller keeps the attempt
1104|    // files and makes the run `artifact_error` rather than deleting them and reporting `done`.
1105|    let mut f = std::fs::OpenOptions::new()
1106|        .create(true)
1107|        .append(true)
1108|        .open(&path)
1109|        .map_err(|e| format!("could not open events.jsonl to append the resume ({e})"))?;
1110|    let mut write = |bytes: &[u8]| -> Result<(), String> {
1111|        f.write_all(bytes)
1112|            .map_err(|e| format!("could not append to events.jsonl ({e})"))
1113|    };
1114|    if needs_nl {
1115|        write(b"\n")?;
1116|    }
1117|    let sep = format!(
1118|        "{{\"type\":\"c3\",\"subtype\":\"resume\",\"n\":{n},\"at\":\"{}\"}}\n",
1119|        Utc::now().to_rfc3339()
1120|    );
1121|    write(sep.as_bytes())?;
1122|    let trimmed = attempt_events.trim_end_matches(['\n', '\r']);
1123|    if !trimmed.is_empty() {
1124|        write(trimmed.as_bytes())?;
1125|        write(b"\n")?;
1126|    }
1127|    f.flush()
1128|        .map_err(|e| format!("could not flush events.jsonl ({e})"))?;
1129|    f.sync_all()
1130|        .map_err(|e| format!("could not sync events.jsonl ({e})"))?;
1131|    Ok(())
1132|}
1133|
1134|/// Resume the child once: relaunch with `--resume`, append the attempt to `events.jsonl`,
1135|/// recompute every artifact over the whole record, bump `quota.resumes`, and make the record final
1136|/// again (quota, exhausted, done, died or timeout). Returns the new status.
1137|fn resume_once(renv: &ResumeEnv, rec_dir: &Path) -> Result<String, String> {
1138|    let rec = read_record(rec_dir)
1139|        .ok()
1140|        .flatten()
1141|        .ok_or_else(|| "the work record vanished".to_string())?;
1142|    let n = rec.quota.as_ref().map(|q| q.resumes).unwrap_or(0) + 1;
1143|    // (0.2.4, F89-2) Claim the record under the task admission lock BEFORE spawning: two concurrent
1144|    // resumes of one record, or a fresh start racing a resume, find it already live and refuse.
1145|    let work_root = rec_dir.parent().unwrap_or(rec_dir).to_path_buf();
1146|    let rec = claim_for_spawn(&work_root, rec_dir, n)?;
1147|    println!(
1148|        "{TOOL}: resuming work run {} ({} :: {}) - resume {}/{}",
1149|        rec.id, rec.provider, rec.model, n, renv.max_resumes
1150|    );
1151|    // (0.2.4, F89-2) Per-attempt file names (never a fixed path two resumes could overwrite).
1152|    let tmp_events = rec_dir.join(format!(".events-resume-{n}.jsonl"));
1153|    let tmp_stderr = rec_dir.join(format!(".stderr-resume-{n}"));
1154|    let _ = std::fs::remove_file(&tmp_events);
1155|    let _ = std::fs::remove_file(&tmp_stderr);
1156|    let spawn = SpawnRequest {
1157|        launcher: &renv.launcher,
1158|        argv: &renv.argv,
1159|        cwd: &renv.repo_root,
1160|        prompt_delivery: renv.prompt_delivery,
1161|        stdin_text: &renv.stdin_text,
1162|        events_path: &tmp_events,
1163|        stderr_path: &tmp_stderr,
1164|        timeout: Duration::from_secs(renv.timeout_sec.max(1) as u64),
1165|        stall_sec: 0,
1166|        kick_path: None,
1167|        tool_flight: None,
1168|        on_running: None,
1169|        on_kill: None,
1170|        env: renv.env.as_deref(),
1171|        crt_quote: renv.crt_quote,
1172|        budget: None,
1173|    };
1174|    let result = run_turn(&spawn);
1175|    let attempt_events = std::fs::read_to_string(&tmp_events).unwrap_or_default();
1176|    let attempt_stderr = std::fs::read_to_string(&tmp_stderr).unwrap_or_default();
1177|
1178|    let (status, quota_text, reset_at, reason) = classify_attempt(
1179|        renv.engine,
1180|        &attempt_events,
1181|        &attempt_stderr,
1182|        result.stop == crate::engines::subprocess::TurnStop::Timeout,
1183|        result.exit_code,
1184|    );
1185|    // (0.2.4, F89-3) Append the attempt to events.jsonl durably FIRST; the per-attempt files are
1186|    // deleted only after the append succeeded and was flushed. A failed append keeps them and
1187|    // makes the run `artifact_error` (never `done`, never a deleted-then-lost report).
1188|    if let Err(e) = append_resume(rec_dir, n, &attempt_events) {
1189|        let _ = finish_artifact_error(rec_dir, result.exit_code, &e);
1190|        return Ok("artifact_error".to_string());
1191|    }
1192|    let _ = std::fs::remove_file(&tmp_events);
1193|    let _ = std::fs::remove_file(&tmp_stderr);
1194|
1195|    let before = rec.baseline.clone();
1196|    let before_hashes = rec.baseline_hashes.clone();
1197|    let mut nrec =
1198|        match refresh_artifacts(renv.engine, rec_dir, &renv.repo_root, &before, &before_hashes) {
1199|            Ok(r) => r,
1200|            Err(e) => {
1201|                let _ = finish_artifact_error(rec_dir, result.exit_code, &e);
1202|                return Ok("artifact_error".to_string());
1203|            }
1204|        };
1205|    nrec.exit_code = result.exit_code.map(|c| c as i64);
1206|    nrec.ended = Some(iso_now());
1207|    nrec.status = status.clone();
1208|    nrec.error = if status == "died" { reason } else { String::new() };
1209|    if status == "quota" {
1210|        let exhausted = n >= renv.max_resumes;
1211|        nrec.quota = Some(build_quota(
1212|            &quota_text,
1213|            reset_at,
1214|            renv.window_sec,
1215|            n,
1216|            exhausted,
1217|        ));
1218|    } else if let Some(q) = nrec.quota.as_mut() {
1219|        // success/death after a quota: keep the last evidence, record how many resumes it took
1220|        q.resumes = n;
1221|    }
1222|    write_record(rec_dir, &nrec)?;
1223|    print_run_line(&nrec);
1224|    if !result.started {
1225|        return Err(format!(
1226|            "the claude process did not start ({})",
1227|            result.error.unwrap_or_else(|| "no reason given".into())
1228|        ));
1229|    }
1230|    Ok(status)
1231|}
