1233|/// A foreground run parked on quota: print the resume time and the exact resume command, exit 3;
1234|/// or, when the resume cap is spent, report it and exit 1.
1235|fn foreground_quota(o: &Options, rec_dir: &Path, rec: &RunRecord) -> i32 {
1236|    let q = rec.quota.clone().unwrap_or_default();
1237|    let collab_flag = if o.collab_dir != ".collab" && !o.collab_dir.is_empty() {
1238|        format!(" --collab-dir \"{}\"", o.collab_dir)
1239|    } else {
1240|        String::new()
1241|    };
1242|    if q.exhausted {
1243|        eprintln!(
1244|            "{TOOL}: work run {} hit its usage limit and spent the resume cap ({}): {}. It needs a human; the record is at {}.",
1245|            rec.id,
1246|            eff_max_resumes_rec(o, rec),
1247|            q.text,
1248|            rec_dir.display()
1249|        );
1250|        return 1;
1251|    }
1252|    println!("{TOOL}: work run {} hit a usage limit: {}", rec.id, q.text);
1253|    println!("resume at : {} ({})", local_time(&q.resume_at), q.resume_at);
1254|    println!(
1255|        "resume now: c3 work --task {}{} --resume {}",
1256|        o.task, collab_flag, rec.id
1257|    );
1258|    3
1259|}
1260|
1261|/// The detached alarm: the background does NOT exit on quota. It parks the run `waiting_quota`,
1262|/// sleeps in slices (waking on the kick file), resumes the child in-process when the window
1263|/// resets, and repeats on a further quota hit until the cap. Returns the final exit code.
1264|fn run_alarm(o: &Options, rec_dir: &Path) -> i32 {
1265|    let rec0 = match read_record(rec_dir) {
1266|        Ok(Some(r)) => r,
1267|        _ => return 1,
1268|    };
1269|    let renv = match resume_env(o, &rec0, rec_dir) {
1270|        Ok(e) => e,
1271|        Err(why) => {
1272|            eprintln!("{TOOL}: cannot arm the quota resume for {}: {why}", rec0.id);
1273|            return 1;
1274|        }
1275|    };
1276|    let kick = rec_dir.join(".kick");
1277|    loop {
1278|        let rec = match read_record(rec_dir) {
1279|            Ok(Some(r)) => r,
1280|            _ => return 1,
1281|        };
1282|        if !record::is_pending(&rec.status) && rec.status != "quota" {
1283|            return exit_for(&rec.status);
1284|        }
1285|        let q = match &rec.quota {
1286|            Some(q) => q.clone(),
1287|            None => return 1,
1288|        };
1289|        if q.exhausted {
1290|            return 1;
1291|        }
1292|        // park the run waiting_quota (the background stays alive; its pid is kept)
1293|        if rec.status != "waiting_quota" {
1294|            let mut wrec = rec.clone();
1295|            wrec.status = "waiting_quota".into();
1296|            let _ = write_record(rec_dir, &wrec);
1297|            println!(
1298|                "{TOOL}: work run {} is waiting for its usage limit to reset, until {} (resume {}/{})",
1299|                rec.id,
1300|                local_time(&q.resume_at),
1301|                q.resumes,
1302|                renv.max_resumes
1303|            );
1304|        }
1305|        let resume_at = parse_utc(&q.resume_at);
1306|        loop {
1307|            match next_action(
1308|                Utc::now(),
1309|                resume_at,
1310|                kick.exists(),
1311|                q.resumes,
1312|                renv.max_resumes,
1313|            ) {
1314|                AlarmAction::Sleep(d) => std::thread::sleep(d),
1315|                AlarmAction::Resume => {
1316|                    let _ = std::fs::remove_file(&kick);
1317|                    break;
1318|                }
1319|                AlarmAction::GiveUp => {
1320|                    let mut er = rec.clone();
1321|                    if let Some(qq) = er.quota.as_mut() {
1322|                        qq.exhausted = true;
1323|                    }
1324|                    er.status = "quota".into();
1325|                    let _ = write_record(rec_dir, &er);
1326|                    return 1;
1327|                }
1328|            }
1329|        }
1330|        match resume_once(&renv, rec_dir) {
1331|            Ok(status) => {
1332|                if status != "quota" {
1333|                    return exit_for(&status);
1334|                }
1335|            }
1336|            Err(why) => {
1337|                eprintln!("{TOOL}: resume of work run {} failed: {why}", rec.id);
1338|                return 1;
1339|            }
1340|        }
1341|    }
1342|}
1343|
1344|/// `--resume`/`--kick`: find the run and act. `--kick` wakes a sleeping detached run (or resumes a
1345|/// foreground quota run directly); `--resume` resumes a `quota`/`timeout` run here and now.
1346|fn resume_or_kick(o: &Options) -> i32 {
1347|    let (_repo_root, _collab, task_dir) = match prepare_paths(o) {
1348|        Ok(p) => p,
1349|        Err(why) => return refuse(&why),
1350|    };
1351|    let work_root = task_dir.join("work");
1352|    if o.kick {
1353|        return do_kick(o, &work_root);
1354|    }
1355|    let (rec_dir, rec) = match pick_run(&work_root, &o.id, &["quota", "timeout"]) {
1356|        Ok(x) => x,
1357|        Err(why) => return refuse(&why),
1358|    };
1359|    do_resume_foreground(o, &rec_dir, &rec)
1360|}
1361|
1362|fn do_kick(o: &Options, work_root: &Path) -> i32 {
1363|    let (rec_dir, rec) = match pick_run(work_root, &o.id, &["waiting_quota", "quota"]) {
1364|        Ok(x) => x,
1365|        Err(why) => return refuse(&why),
1366|    };
1367|    match rec.status.as_str() {
1368|        "waiting_quota" => {
1369|            if let Err(e) = std::fs::write(rec_dir.join(".kick"), b"1") {
1370|                return refuse(&format!("could not write the kick file ({e})"));
1371|            }
1372|            println!(
1373|                "{TOOL}: kicked work run {} - its sleeper will resume now.",
1374|                rec.id
1375|            );
1376|            0
1377|        }
1378|        "quota" => do_resume_foreground(o, &rec_dir, &rec),
1379|        other => refuse(&format!(
1380|            "work run {} is in state {other}, not waiting on a quota reset; --kick has nothing to wake.",
1381|            rec.id
1382|        )),
1383|    }
1384|}
1385|
