158|/// How long a pending record may go without a reported pid before it counts as dead
159|/// (the background reports its pid within its first second).
160|const START_GRACE_SEC: i64 = 120;
161|
162|/// Whether a status means the run's background is still supposed to be alive: `running`, or
163|/// `waiting_quota` while a detached run's alarm sleeps until the quota window resets.
164|pub fn is_pending(status: &str) -> bool {
165|    status == "running" || status == "waiting_quota"
166|}
