410|/// hash, so it is listed; a pre-dirty path the worker edited further differs, so it is listed; a
411|/// pre-dirty path left untouched matches, so it is not). After-order, deduplicated.
412|pub fn files_changed(
413|    baseline_hashes: &BTreeMap<String, String>,
414|    after: &[String],
415|    repo: &Path,
416|) -> Vec<String> {
