537|/// The child session id a resume continues, read from the finished event stream: codex names a
538|/// thread in its stream (parsed here); claude and muse mint theirs before the launch, so the
539|/// record already holds it and this returns `""`.
540|pub fn session_from_events(engine: WorkerEngine, events_text: &str) -> String {
541|    match engine {
542|        WorkerEngine::Codex => crate::engines::codex::parse_thread_id(events_text),
543|        WorkerEngine::Claude | WorkerEngine::Muse => String::new(),
544|    }
545|}
